const supersedeAccessRequest = `-- name: SupersedeAccessRequest :one
UPDATE access_requests SET status = 'expired', finished_at = ?
WHERE id = +? AND status = 'pending'
RETURNING id, nonce, org_id, project_id, environment_id, status, via, operation, title, "action", args, fingerprint, reason, token_id, requested_by, audit_mark, upload, created_at, expires_at, decided_by, decided_at, comment, result, error, finished_at, ask_user_id, user_id
`

type SupersedeAccessRequestParams struct {
	FinishedAt *time.Time
	ID         int64
}

// SupersedeAccessRequest ends a pending request a newer call of the same
// kind replaces (a newer push or upload). The newer call is filed as a new
// request, so an approval of this one can never run it.
func (q *Queries) SupersedeAccessRequest(ctx context.Context, arg SupersedeAccessRequestParams) (AccessRequest, error) {
	row := q.db.QueryRowContext(ctx, supersedeAccessRequest, arg.FinishedAt, arg.ID)
	var i AccessRequest
	err := row.Scan(
		&i.ID,
		&i.Nonce,
		&i.OrgID,
		&i.ProjectID,
		&i.EnvironmentID,
		&i.Status,
		&i.Via,
		&i.Operation,
		&i.Title,
		&i.Action,
		&i.Args,
		&i.Fingerprint,
		&i.Reason,
		&i.TokenID,
		&i.RequestedBy,
		&i.AuditMark,
		&i.Upload,
		&i.CreatedAt,
		&i.ExpiresAt,
		&i.DecidedBy,
		&i.DecidedAt,
		&i.Comment,
		&i.Result,
		&i.Error,
		&i.FinishedAt,
		&i.AskUserID,
		&i.UserID,
	)
	return i, err
}
